function icon(name){return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${PATHS[name]||PATHS.house}"/></svg>`;}
function hydrate(root=document){root.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));}
function esc(s){return String(s).replace(/[&<>"']/g,v=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[v]));}
hydrate();
const SAVE_KEY='valdora-save-v1';let world,loaded=false,storageAvailable=true;
try{const saved=localStorage.getItem(SAVE_KEY);if(saved){const d=JSON.parse(saved);world=new World(d.seed,d);loaded=true;}}catch{storageAvailable=false;}
if(!world)world=new World();
let renderer;
try { renderer=new Renderer($('world'),$('minimap'),world); document.body.classList.add('graphics-3d'); } catch(error) { console.error('No se pudo iniciar la vista 3D:',error); const previous=$('world'),replacement=previous.cloneNode(false);previous.replaceWith(replacement);renderer=new Renderer2D(replacement,$('minimap'),world);$('graphics-status').hidden=false;$('graphics-status').textContent='La vista 3D necesita WebGL 2 y aceleración gráfica. Se ha activado la vista 2D compatible.'; }
// Este ajuste se aplica siempre, incluso al recuperar una partida anterior.
activateStartupQuality(renderer,document.body);
function updateQualityIndicator(){
 const is3d=document.body.classList.contains('graphics-3d');
 const element=$('quality-indicator');
 element.textContent=qualityLabel(renderer.quality,is3d);
 element.title=is3d?'Calidad actual. Puedes cambiarla en Ajustes; el siguiente inicio vuelve a Ligera.':'Vista compatible sin WebGL 3D';
 document.body.dataset.graphicsQuality=renderer.quality;
}
updateQualityIndicator();
$('world').setAttribute('aria-label','Mapa interactivo. Selecciona un edificio y haz clic para construir. Para caminos y puentes, arrastra entre los dos extremos.');
if(!renderer.rotate){for(const id of ['rotate-left','rotate-right','tilt-camera'])$(id).disabled=true;document.querySelector('.navigation-tip').textContent='Arrastrar: mover · Rueda: zoom · Caminos: arrastrar y soltar';}
$('world-loading').remove();
let category='Todos',mode=null,selected=null,modalResume=0,lastUi=0,lastSave=0,accumulator=0,lastTime=0,gameOverShown=false,sound=false,audioContext=null,soundTimer=null;
const order=['house','farm','gatherer','forester','woodcutter','fisher','pasture','quarry','well','market','warehouse','road','bridge'];
const resourceElements={};
for(const [key,r]of Object.entries(RESOURCES)){const e=document.createElement('div');e.className='resource';e.style.setProperty('--resource',r.color);e.innerHTML=`${icon(r.icon)}<div><strong>0</strong><span class="trend"></span><small>${r.name}</small></div>`;$('resource-bar').append(e);resourceElements[key]=e;e.addEventListener('mouseenter',()=>{const prod=world.production[key];showTooltip(e,`${r.name} · ${Math.floor(world.resources[key])} / ${world.storage}`,`${key==='food'?`Reservas para ${world.foodDays} días sin producción. `:''}Balance del último día: ${prod>=0?'+':''}${prod.toFixed(1)}.`,key==='firewood'?'El consumo aumenta en invierno.':'Los almacenes amplían la capacidad.');});e.addEventListener('mouseleave',hideTooltip);}
function renderBuildList(){const list=$('build-list');list.innerHTML='';for(const type of order){const d=BUILDINGS[type];if(category!=='Todos'&&d.category!==category)continue;const btn=document.createElement('button');btn.className='build-item'+(mode===type?' active':'');btn.dataset.building=type;btn.style.setProperty('--building-color',d.color);btn.setAttribute('aria-label',`Construir ${d.name}`);btn.setAttribute('aria-pressed',String(mode===type));btn.innerHTML=`<span class="building-art">${icon(d.icon)}</span><span><strong>${d.name}</strong><span class="cost">${Object.entries(d.cost).map(([k,n])=>`<span data-cost="${k}" class="${world.resources[k]<n?'unaffordable':''}">${icon(RESOURCES[k].icon)}${n}</span>`).join('')}</span></span><span class="shortcut">+</span>`;btn.addEventListener('click',()=>chooseBuilding(type));btn.addEventListener('mouseenter',()=>showTooltip(btn,d.name,d.description,d.detail));btn.addEventListener('mouseleave',hideTooltip);list.append(btn);}}
function chooseBuilding(type){cancelLine();closeSelection();hideTooltip();mode=mode===type?null:type;renderer.buildMode=mode;renderer.gatherMode=false;$('gather-btn').classList.remove('active');$('world').classList.toggle('building',!!mode);renderBuildList();updateHint();$('sidebar').classList.remove('open');if(mode)toast(type==='road'?'Camino: arrastra entre dos puntos y suelta para construir.':type==='bridge'?'Puente: arrastra de una orilla a la otra.':`${BUILDINGS[type].name}: elige un terreno libre.`);}
function cancelMode(){cancelLine();mode=null;renderer.buildMode=null;renderer.gatherMode=false;$('gather-btn').classList.remove('active');$('world').classList.remove('building');$('build-hint').hidden=true;renderBuildList();}
function updateHint(){const el=$('build-hint');if(!mode&&!renderer.gatherMode){el.hidden=true;return;}el.hidden=false;if(mode==='road'||mode==='bridge'){const plan=renderer.linePreview;el.classList.toggle('invalid',!!plan&&!plan.ok);const cost=plan?Object.entries(plan.cost).map(([k,n])=>`${n} ${RESOURCES[k].name.toLowerCase()}`).join(' · '):'';el.innerHTML=`<strong>${BUILDINGS[mode].name}${plan?` · ${plan.cells.length} tramos`:''}</strong><span>${plan?`${cost||'Sin coste'} · ${plan.reason}`:mode==='bridge'?'Arrastra desde una orilla hasta la otra · Suelta para construir':'Arrastra entre dos puntos · Vista previa y coste antes de soltar'}</span>`;return;}if(renderer.gatherMode){el.classList.remove('invalid');el.innerHTML='<strong>Recoger recursos</strong><span>Marca árboles y rocas · Los trabajadores libres los recogerán · Esc para salir</span>';return;}const d=BUILDINGS[mode],r=renderer.hover?world.canPlace(mode,renderer.hover.x,renderer.hover.y):{ok:true,reason:'Elige terreno libre · Esc para cancelar'};el.classList.toggle('invalid',!r.ok);el.innerHTML=`<strong>${d.name} <span style="display:inline;margin-left:5px;font-size:9px;color:#9fb18f">${d.w} × ${d.h}</span></strong><span>${r.reason}</span>`;}
function toggleGather(){const active=renderer.gatherMode;cancelMode();closeSelection();renderer.gatherMode=!active;$('gather-btn').classList.toggle('active',!active);$('world').classList.toggle('building',!active);updateHint();$('sidebar').classList.remove('open');}
function showTooltip(e,title,description,detail=''){if(window.innerWidth<701||!$('modal-overlay').hidden)return;const t=$('tooltip');t.innerHTML=`<h4>${esc(title)}</h4><p>${esc(description)}</p><small>${esc(detail)}</small>`;t.hidden=false;const r=e.getBoundingClientRect();let x=r.right+12,y=r.top;if(r.top<90){x=r.left;y=r.bottom+12;}if(x+235>innerWidth)x=r.left-247;t.style.left=Math.max(8,x)+'px';t.style.top=Math.min(innerHeight-t.offsetHeight-10,y)+'px';}
function hideTooltip(){$('tooltip').hidden=true;}
function toast(msg,type='info'){const e=document.createElement('div');e.className='toast '+type;e.textContent=msg;$('toast-container').append(e);setTimeout(()=>e.remove(),3700);while($('toast-container').children.length>3)$('toast-container').firstChild.remove();}
function selectBuilding(id){cancelMode();selected=id;renderer.selected=id;renderSelection();renderer.updateSelection?.();}
function closeSelection(){selected=null;renderer.selected=null;$('selection-panel').hidden=true;$('quarry-inspector').hidden=true;renderer.updateSelection?.();}
function renderSelection(){const b=world.buildings.find(b=>b.id===selected);if(!b){closeSelection();return;}const d=BUILDINGS[b.type],panel=$('selection-panel');
 const quarryReserve=b.type==='quarry'?world.stoneAround(b):null;
 const quarryState=b.type==='quarry'?(b.progress<1?'En construcción':quarryReserve===0?'Agotado':b.paused?'Pausada':b.workers===0?'Sin trabajadores':'En explotación'):null;
 panel.hidden=false;panel.innerHTML=`<button class="panel-close" aria-label="Cerrar panel">${icon('close')}</button><div class="panel-heading"><span class="building-art" style="--building-color:${d.color}">${icon(d.icon)}</span><div><h3>${d.name}</h3><small>${b.progress<1?'En construcción':b.paused?'Producción pausada':d.maxWorkers?b.workers?'En funcionamiento':'Sin trabajadores':'Construido'}</small></div></div><p class="panel-description">${d.description}</p>${b.progress<1?`<div class="panel-stat"><span>Construcción</span><strong>${Math.round(b.progress*100)}%</strong></div><div class="progress-bar"><i style="width:${b.progress*100}%"></i></div><p class="panel-description">${world.builders?`${world.builders} trabajadores disponibles para construir.`:'Necesitas liberar al menos un trabajador de otro edificio.'}</p>`:`<div class="panel-stat"><span>${d.detail}</span></div>${d.maxWorkers?`<div class="panel-stat"><span>Trabajadores</span><div class="worker-controls"><button id="worker-minus" aria-label="Quitar trabajador" ${b.workers===0?'disabled':''}>${icon('minus')}</button><strong>${b.workers} / ${d.maxWorkers}</strong><button id="worker-plus" aria-label="Añadir trabajador" ${b.workers>=d.maxWorkers||world.idle===0?'disabled':''}>${icon('plus')}</button></div></div>`:''}${b.type==='gatherer'||b.type==='forester'?`<div class="panel-stat"><span>Bosque cercano</span><strong>${Math.round(world.forestAt(b,b.type==='forester'?8:7)*100)}%</strong></div>`:''}${b.type==='house'?`<div class="panel-stat"><span>Plazas totales en la aldea</span><strong>${world.population} / ${world.capacity}</strong></div>`:''}`}${b.type==='quarry'? `<section class="quarry-reserve" aria-label="Información de piedra de la cantera"><div class="panel-stat"><span>Reserva de piedra en el radio</span><strong data-quarry-reserve>${quarryReserve.toLocaleString('es')} unidades</strong></div><div class="panel-stat"><span>Yacimiento</span><strong data-quarry-status>${quarryState}</strong></div><div class="panel-stat"><span>Radio de extracción</span><strong>9 casillas</strong></div></section>`:''}<div class="panel-actions">${d.maxWorkers&&b.progress>=1?`<button id="toggle-production">${b.paused?'Reanudar':'Pausar'} producción</button>`:''}${b.type!=='hall'?`<button class="danger" id="demolish-btn">${b.progress<1?'Cancelar obra':'Demoler'}</button>`:''}</div>`;
 // Una tarjeta grande dentro de la ficha y un indicador independiente sobre el mapa:
 // el dato sigue visible aunque el jugador no desplace el panel hacia abajo.
 const inspector=$('quarry-inspector');
 if(b.type==='quarry'){
  const header=document.createElement('div');
  header.className='quarry-reserve-highlight';
  const caption=document.createElement('small');caption.textContent='PIEDRA DISPONIBLE EN EL ÁREA';
  const value=document.createElement('strong');value.setAttribute('data-quarry-primary','');
  value.textContent=quarryReserve.toLocaleString('es')+' unidades';
  header.append(caption,value);
  panel.querySelector('.panel-heading').after(header);
  inspector.hidden=false;
  inspector.textContent='CANTERA · '+quarryReserve.toLocaleString('es')+' piedras disponibles · '+quarryState+' · Radio 9';
  inspector.dataset.reserve=String(quarryReserve);
 }else{
  inspector.hidden=true;
 }
 panel.querySelector('.panel-close').onclick=closeSelection;if($('worker-minus'))$('worker-minus').onclick=()=>{world.changeWorkers(b.id,-1);updateUI();};if($('worker-plus'))$('worker-plus').onclick=()=>{world.changeWorkers(b.id,1);updateUI();};if($('toggle-production'))$('toggle-production').onclick=()=>{b.paused=!b.paused;renderSelection();};if($('demolish-btn'))$('demolish-btn').onclick=()=>confirmDemolish(b);
}
function confirmDemolish(b){showModal(`<div class="modal-eyebrow">GESTIÓN DE LA ALDEA</div><h2>¿${b.progress<1?'Cancelar la obra':'Demoler el edificio'}?</h2><p>Se eliminará <strong>${BUILDINGS[b.type].name.toLowerCase()}</strong> y recuperarás el 50 % de sus materiales.${b.type==='house'?' La aldea perderá 4 plazas de alojamiento.':''}</p><div class="modal-actions"><button class="btn-secondary" id="cancel-demolish">Conservar edificio</button><button class="btn-danger" id="confirm-demolish">${b.progress<1?'Cancelar obra':'Demoler'}</button></div>`);$('cancel-demolish').onclick=closeModal;$('confirm-demolish').onclick=()=>{world.demolish(b.id);closeSelection();renderer.invalidate();closeModal();updateUI();save(false);};}
function updateUI(){for(const [k,e]of Object.entries(resourceElements)){e.querySelector('strong').textContent=Math.floor(world.resources[k]).toLocaleString('es');const n=world.production[k];e.querySelector('.trend').textContent=world.totalDays?`${n>=0?'+':''}${n.toFixed(1)}`:'';e.querySelector('.trend').classList.toggle('negative',n<0);e.classList.toggle('low',k==='food'&&world.foodDays<8||k==='firewood'&&world.season===3&&world.resources.firewood<10);e.title=`${RESOURCES[k].name}: ${Math.floor(world.resources[k])} / ${world.storage}`;}
 $('population').textContent=world.population;$('housing').textContent=`/ ${world.capacity} plazas`;$('settlement-tag').textContent=world.population<12?'Campamento':world.population<24?'Aldea':'Pueblo';$('health').textContent=Math.round(world.health)+'%';$('happiness').textContent=Math.round(world.happiness)+'%';$('health-bar').style.width=world.health+'%';$('happy-bar').style.width=world.happiness+'%';$('worker-summary').textContent=`${world.workers} asignados · ${world.idle} libres para construir`;$('building-count').textContent=world.buildings.length+' edificios';$('seed-label').textContent=world.seed+(world.terrainVersion===3?` · Región X ${world.viewRegion.x}, Y ${world.viewRegion.y} · ${world.loadedChunks} sectores en memoria`:' · valle clásico');
 document.querySelectorAll('.build-item').forEach(btn=>{const d=BUILDINGS[btn.dataset.building];btn.querySelectorAll('[data-cost]').forEach(c=>c.classList.toggle('unaffordable',world.resources[c.dataset.cost]<d.cost[c.dataset.cost]));});
 const goal=world.goals.find(g=>!world.milestones.includes(g.id));$('mission-title').textContent=goal?.title||'Un valle lleno de vida';$('mission-desc').textContent=goal?.text||'Has cumplido todos los objetivos. Sigue construyendo.';$('mission-progress').innerHTML=world.goals.map(g=>`<i class="${world.milestones.includes(g.id)?'done':''}"></i>`).join('');
 const s=SEASONS[world.season];$('season-label').innerHTML=`${s.name} <span>Año ${world.year}</span>`;$('day-label').textContent=`Día ${world.day} de 30`;$('season-track').firstElementChild.style.width=world.day/30*100+'%';$('season-icon').innerHTML=icon(['sprout','sun','leaf','snow'][world.season]);$('season-icon').style.color=s.color;$('temperature').textContent=world.temperature+'°';$('temperature').nextElementSibling.textContent=world.season===3?'Heladas':world.season===1?'Cálido':'Templado';$('weather-title').textContent=['El valle despierta','Días de abundancia','El invierno se acerca','El valle bajo la nieve'][world.season];$('weather-desc').textContent=['La primavera es tiempo de construir.','Tus campos producen a pleno ritmo.','Prepara tus reservas de comida y leña.','Abrigo, alimento y un hogar.'][world.season];$('season-notice').firstElementChild.innerHTML=icon(['sprout','sun','leaf','snow'][world.season]);$('pause-btn').innerHTML=icon(world.speed?'pause':'play');$('pause-btn').setAttribute('aria-label',world.speed?'Pausar':'Continuar');$('time-state').textContent=world.speed?'El tiempo avanza':'Tiempo en pausa';document.querySelectorAll('[data-speed]').forEach(e=>e.classList.toggle('active',world.speed===Number(e.dataset.speed)));
 $('event-count').textContent=world.events.length;$('event-list').innerHTML=world.events.slice(0,12).map(e=>`<div class="event ${e.type}"><time>${esc(e.date)}</time>${esc(e.text)}</div>`).join('');$('zoom-label').textContent=Math.round(renderer.zoom*100)+'%';if(selected)renderSelection();if(mode)updateHint();if(world.gameOver&&!gameOverShown){gameOverShown=true;showGameOver();}
}
function save(manual=true){try{if(world.terrainVersion===3)world.cameraPosition=renderer.camera&&renderer.focus?{...renderer.camera}:renderer.unproject(renderer.width/2,renderer.height/2);localStorage.setItem(SAVE_KEY,JSON.stringify(world.serialize()));storageAvailable=true;$('save-status').textContent='Partida guardada en este navegador';if(manual)toast('Partida guardada. Tu valle te esperará aquí.');return true;}catch{storageAvailable=false;$('save-status').textContent='Guardado local no disponible';if(manual)toast('No se puede guardar aquí. Exporta la partida desde el menú.','danger');return false;}}
function showModal(content,wide=false){hideTooltip();if($('modal-overlay').hidden){modalResume=world.speed;world.speed=0;}$('modal').className='modal'+(wide?' wide':'');$('modal').innerHTML=`<button class="close-modal" aria-label="Cerrar">${icon('close')}</button>${content}`;$('modal-overlay').hidden=false;let title=$('modal').querySelector('h2');if(title)title.id='modal-title';$('modal').querySelector('.close-modal').onclick=closeModal;updateUI();setTimeout(()=>$('modal').querySelector('input, .btn-primary, button')?.focus(),20);}
