function showWelcome(){showModal(`<div class="modal-hero">${icon('valley')}</div><div class="modal-eyebrow">VALDORA · UN MUNDO EN 3D</div><h2>Todo empieza<br>con un nuevo hogar.</h2><p>Ocho colonos, un valle por descubrir y un invierno en el horizonte. Construye una aldea donde merezca la pena quedarse.</p><div class="guide-steps"><div class="guide-step"><span><strong>Asegura los alimentos.</strong> Construye un campo y una cabaña recolectora cerca del bosque.</span></div><div class="guide-step"><span><strong>Prepara el invierno.</strong> Un puesto forestal produce madera; un leñador la convierte en leña.</span></div><div class="guide-step"><span><strong>Dale espacio a tu aldea.</strong> Construye casas para recibir nuevos habitantes cada estación.</span></div></div><div class="modal-actions"><button class="btn-primary" id="start-game">Fundar mi aldea ${icon('arrowright')}</button><button class="btn-secondary" id="welcome-help">Ver controles</button></div><p class="modal-note">Mundo procedural continuo · Exploración sin fronteras · Guardado automático</p>`);$('start-game').onclick=()=>{modalResume=1;closeModal();save(false);};$('welcome-help').onclick=showHelp;}
function showHelp(){showModal(`<div class="modal-eyebrow">GUÍA DEL COLONO</div><h2>Un pequeño gran comienzo.</h2><div class="guide-steps"><div class="guide-step"><span><strong>Construye.</strong> Para caminos y puentes, arrastra entre dos puntos y suelta: el recorrido y su coste aparecen antes de construir. Los puentes van de orilla a orilla. Para el resto, elige un edificio en la izquierda y haz clic en el terreno. El verde indica una ubicación válida. Las obras necesitan tiempo y al menos un trabajador libre.</span></div><div class="guide-step"><span><strong>Asigna trabajadores.</strong> Los edificios nuevos reciben trabajadores automáticamente. Haz clic en ellos para ajustar la plantilla. Conserva uno libre para construir y recoger recursos.</span></div><div class="guide-step"><span><strong>Alimenta a tus habitantes.</strong> Cada persona consume 0,45 alimentos al día. Los campos descansan en invierno; combina cultivos, recolección, pesca y ganado.</span></div><div class="guide-step"><span><strong>Crece con cuidado.</strong> Cada casa aloja a 4 personas. Si hay espacio, felicidad y comida, llegan hasta 2 colonos al empezar cada estación. Las estaciones duran 30 días.</span></div><div class="guide-step"><span><strong>Protege tu aldea.</strong> En invierno cada persona consume 0,2 de leña al día. Ocho días sin comida o doce pasando frío empiezan a causar muertes.</span></div></div><div class="hotkeys"><div><kbd>Espacio</kbd> Pausar / continuar</div><div><kbd>1 / 2 / 3</kbd> Velocidad 1× / 2× / 5×</div><div><kbd>G</kbd> Recoger madera y piedra</div><div><kbd>C</kbd> Centrar la cámara</div><div><kbd>Esc</kbd> Cancelar / cerrar</div><div><kbd>WASD</kbd> Mover la cámara</div><div><kbd>Q / E</kbd> Girar la vista 3D</div><div><kbd>Botón derecho</kbd> Girar e inclinar</div></div><p class="modal-note">Arrastra el mapa para explorar; usa la rueda para acercarte. Mantén pulsado el botón derecho y arrastra para girar e inclinar la cámara 3D. En móvil, arrastra con un dedo y usa los botones + / −. Haz clic en el minimapa para desplazarte. Un día dura 2,5 segundos a velocidad 1×.</p><div class="modal-actions"><button class="btn-primary" id="help-close">Volver al valle ${icon('arrowright')}</button></div>`,true);$('help-close').onclick=()=>{if(!loaded&&world.totalDays===0&&modalResume===0)modalResume=1;closeModal();};}
function showGoals(){showModal(`<div class="modal-eyebrow">EL PRIMER CAPÍTULO</div><h2>Echa raíces en el valle.</h2><p>Cuatro pequeños pasos para transformar un campamento en una aldea próspera.</p>${world.goals.map(g=>`<div class="goal-row"><span class="goal-check ${world.milestones.includes(g.id)?'done':''}">${icon(world.milestones.includes(g.id)?'check':'flag')}</span><div><strong>${g.title}</strong><p>${g.text}</p></div></div>`).join('')}<div class="modal-actions"><button class="btn-primary" id="goals-close">Seguir construyendo</button></div>`);$('goals-close').onclick=closeModal;}
function showPopulation(){showModal(`<div class="modal-eyebrow">EL CORAZÓN DE VALDORA</div><h2>Gente que hace un hogar.</h2><div class="stats-row"><div><strong>${world.population}</strong><small>HABITANTES</small></div><div><strong>${world.capacity}</strong><small>PLAZAS EN VIVIENDAS</small></div><div><strong>${world.idle}</strong><small>TRABAJADORES LIBRES</small></div></div><p>${world.capacity>world.population?'Hay viviendas disponibles. Con suficiente comida y felicidad, nuevos colonos pueden llegar al cambiar de estación.':'Construye más casas para recibir nuevos habitantes la próxima estación.'}</p><table class="citizens-table"><thead><tr><th>HABITANTE</th><th>EDAD AL LLEGAR</th><th>OCUPACIÓN</th></tr></thead><tbody>${world.citizens.map(c=>`<tr><td>${esc(c.name)}</td><td>${c.age} años</td><td>${c.job?BUILDINGS[world.buildings.find(b=>b.id===c.job)?.type]?.name||'Trabajador':'Construcción / recogida'}</td></tr>`).join('')}</tbody></table><div class="modal-actions"><button class="btn-primary" id="pop-close">Volver al valle</button></div>`,true);$('pop-close').onclick=closeModal;}
function showSettings(){showModal(`<div class="modal-eyebrow">TU RINCÓN DEL MUNDO</div><h2>El valle te espera.</h2><p>Año ${world.year} · ${SEASONS[world.season].name}, día ${world.day}<br>Semilla: <strong>${esc(world.seed)}</strong><br>Región: <strong>${world.terrainVersion===3?`X ${world.viewRegion.x} · Y ${world.viewRegion.y} (origen X ${world.coordinates.x}, Y ${world.coordinates.y})`:'Valle clásico'}</strong></p><div class="settings-grid"><button class="btn-secondary" id="menu-save">${icon('save')} Guardar partida</button><button class="btn-secondary" id="menu-export">${icon('download')} Exportar partida</button><button class="btn-secondary" id="menu-import">${icon('upload')} Importar partida</button><button class="btn-secondary" id="menu-new">${icon('restart')} Nuevo valle</button></div><div class="graphics-settings"><span>Calidad gráfica</span><div><button data-quality="high">Alta</button><button data-quality="medium">Equilibrada</button><button data-quality="low">Ligera</button></div><small>Alta: reflejos, sombras de contacto y vegetación. Ligera: menos detalle, sin reflejos ni sombras.</small></div><p class="modal-note">El progreso se guarda automáticamente cada 20 segundos en este navegador. Exporta una copia para conservarla o llevarla a otro dispositivo.</p><div class="modal-actions"><button class="btn-primary" id="menu-resume">Volver al valle ${icon('play')}</button></div>`);$('menu-save').onclick=()=>save();$('menu-export').onclick=exportSave;$('menu-import').onclick=importSave;$('menu-new').onclick=showNewGame;$('menu-resume').onclick=closeModal;document.querySelectorAll('[data-quality]').forEach(btn=>{btn.classList.toggle('active',btn.dataset.quality===renderer.quality);btn.disabled=!renderer.setQuality;btn.onclick=()=>{renderer.setQuality(btn.dataset.quality);updateQualityIndicator();document.querySelectorAll('[data-quality]').forEach(b=>b.classList.toggle('active',b===btn));};});}
function exportSave(){const blob=new Blob([JSON.stringify(world.serialize(),null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`Valdora-Ano-${world.year}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Copia de la partida exportada.');}
function importSave(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const f=input.files[0];if(!f)return;if(f.size>20e6)throw Error('Archivo demasiado grande');const data=JSON.parse(await f.text());if(typeof data.seed!=='string'||data.seed.length>100||data.buildings.length>100000||data.citizens.length>500)throw Error('Partida no válida');const next=new World(data.seed,data);world=next;renderer.setWorld(world);selected=null;mode=null;accumulator=0;gameOverShown=false;modalResume=0;closeModal();renderBuildList();updateUI();save(false);toast('Partida importada. Pulsa continuar cuando quieras.');}catch{toast('Ese archivo no es una partida válida de Valdora.','danger');}};input.click();}
function showNewGame(){
 const coords=world.coordinates||{x:0,y:0};
 showModal(`<div class="modal-eyebrow">TIERRAS POR DESCUBRIR</div><h2>Elige tu lugar en el mundo.</h2><p>Valdora genera ahora un <strong>mundo continuo</strong> de regiones, con montañas, bosques y ríos. Escoge dónde empezar y explora sin fronteras dentro de la partida. Se cargan solo las zonas cercanas. Las mismas coordenadas y semilla siempre producen el mismo paisaje.</p><label class="form-label" for="seed-input">Semilla del mundo</label><input class="input" id="seed-input" maxlength="40" value="${esc(world.seed)}"><div class="coordinate-fields"><label class="form-label" for="coordinate-x">Coordenada X<input class="input" id="coordinate-x" type="number" min="-1000000" max="1000000" step="1" value="${coords.x}"></label><label class="form-label" for="coordinate-y">Coordenada Y<input class="input" id="coordinate-y" type="number" min="-1000000" max="1000000" step="1" value="${coords.y}"></label></div><div class="coordinate-preview"><canvas id="coordinate-map" width="192" height="192" role="img" aria-label="Vista previa del terreno seleccionado"></canvas><p id="coordinate-info">X/Y eligen la región inicial. Durante la partida podrás continuar explorando en cualquier dirección, sin cambiar de mundo.</p></div><div class="difficulty-note">8 colonos · 160 madera · 90 piedra · 220 alimentos · 75 leña<br>Objetivo: sobrevivir al invierno y alcanzar 16 habitantes.</div><p class="danger-note">La nueva partida sustituirá el guardado actual. Exporta una copia si quieres conservarlo.</p><div class="modal-actions"><button class="btn-secondary" id="back-settings">Volver</button><button class="btn-primary" id="create-world">Fundar en estas coordenadas</button></div>`);
 const selectedCoords=()=>{
  const rawX=$('coordinate-x').value,rawY=$('coordinate-y').value;
  const x=Number(rawX),y=Number(rawY);
  if(!rawX.trim()||!rawY.trim()||!Number.isInteger(x)||!Number.isInteger(y)||Math.abs(x)>1000000||Math.abs(y)>1000000)return null;
  return {x,y};
 };
 const drawPreview=()=>{
  const coords=selectedCoords(),info=$('coordinate-info'),canvas=$('coordinate-map'),ctx=canvas.getContext('2d');
  if(!coords||!ctx){info.textContent='Introduce coordenadas X e Y enteras entre -1.000.000 y 1.000.000.';return;}
  try{
   const preview=new World($('seed-input').value.trim()||'VALDORA-2048',null,coords);
   const counts={water:0,hill:0,grass:0};
   for(const t of preview.tiles){counts[t.type]++;ctx.fillStyle=t.type==='water'?'#5e8d91':t.type==='hill'?'#848780':t.tree?'#476c46':'#8c9b69';ctx.fillRect(t.x*3,t.y*3,3,3);}
   ctx.fillStyle='#f4dca8';ctx.fillRect(90,96,12,12);
   info.textContent=`Región X ${coords.x} · Y ${coords.y}. Llanuras ${Math.round(counts.grass/41)} %, montañas ${Math.round(counts.hill/41)} %, agua ${Math.round(counts.water/41)} %. Punto dorado: asentamiento inicial.`;
  }catch{info.textContent='No se puede generar la vista previa para estas coordenadas.';}
 };
 for(const id of ['seed-input','coordinate-x','coordinate-y'])$(id).addEventListener('input',drawPreview);
 drawPreview();
 $('back-settings').onclick=showSettings;
 $('create-world').onclick=()=>{
  const coords=selectedCoords();if(!coords){toast('Indica coordenadas enteras válidas.','danger');return;}
  const seed=$('seed-input').value.trim()||'VALDORA-2048';world=new World(seed,null,coords);renderer.setWorld(world);category='Todos';mode=null;selected=null;accumulator=0;gameOverShown=false;modalResume=1;closeSelection();cancelMode();document.querySelectorAll('[data-category]').forEach(e=>e.classList.toggle('active',e.dataset.category==='Todos'));closeModal();updateUI();save(false);toast(`Nueva aldea en X ${coords.x}, Y ${coords.y}.`);
 };
}
function showGameOver(){showModal(`<div class="modal-eyebrow">EL SILENCIO DEL VALLE</div><h2>Todo hogar deja una historia.</h2><p>La aldea ha quedado deshabitada después de ${world.totalDays} días. La próxima vez, prepara producción de alimentos para todo el año, un leñador y viviendas suficientes.</p><div class="modal-actions"><button class="btn-secondary" id="end-inspect">Explorar el valle</button><button class="btn-primary" id="end-new">Un nuevo comienzo</button></div>`);$('end-inspect').onclick=closeModal;$('end-new').onclick=showNewGame;}
function setSpeed(n){if(world.gameOver)return;world.speed=n;if(n)world.lastSpeed=n;updateUI();}
function togglePause(){setSpeed(world.speed?0:world.lastSpeed||1);}
function soundToggle(){sound=!sound;$('sound-btn').innerHTML=icon(sound?'sound':'soundoff');$('sound-btn').setAttribute('aria-label',sound?'Desactivar sonido':'Activar sonido');if(sound){try{audioContext=audioContext||new (window.AudioContext||window.webkitAudioContext)();audioContext.resume();chirp();soundTimer=setInterval(chirp,4200);toast('Sonido del bosque activado.');}catch{sound=false;toast('Sonido no disponible en este navegador.');}}else clearInterval(soundTimer);}
function chirp(){if(!sound||!audioContext||document.hidden)return;for(let i=0;i<3;i++){const o=audioContext.createOscillator(),g=audioContext.createGain(),t=audioContext.currentTime+i*.16;o.type='sine';o.frequency.setValueAtTime(1500+Math.random()*800,t);o.frequency.exponentialRampToValueAtTime(2700+Math.random()*600,t+.07);g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.012,t+.02);g.gain.exponentialRampToValueAtTime(.0001,t+.13);o.connect(g);g.connect(audioContext.destination);o.start(t);o.stop(t+.15);}}
document.querySelectorAll('[data-category]').forEach(btn=>btn.addEventListener('click',()=>{category=btn.dataset.category;document.querySelectorAll('[data-category]').forEach(b=>b.classList.toggle('active',b===btn));renderBuildList();}));
