$('pause-btn').onclick=togglePause;$('save-btn').onclick=()=>save();$('help-btn').onclick=showHelp;$('settings-btn').onclick=showSettings;$('population-btn').onclick=showPopulation;$('mission-btn').onclick=showGoals;$('season-notice').onclick=showHelp;$('sound-btn').onclick=soundToggle;$('gather-btn').onclick=toggleGather;
$('event-toggle').onclick=()=>$('event-list').classList.toggle('open');$('center-btn').onclick=()=>{renderer.center();updateUI();};$('brand').onclick=e=>{e.preventDefault();renderer.center();};$('zoom-in').onclick=()=>{renderer.setZoom(renderer.zoom*1.15);updateUI();};$('zoom-out').onclick=()=>{renderer.setZoom(renderer.zoom/1.15);updateUI();};$('mobile-build').onclick=()=>$('sidebar').classList.toggle('open');
$('minimap').onclick=e=>{const r=e.currentTarget.getBoundingClientRect(),ox=world.terrainVersion===3?world.viewRegion.x*64:0,oy=world.terrainVersion===3?world.viewRegion.y*64:0,x=ox+(e.clientX-r.left)/r.width*64,y=oy+(e.clientY-r.top)/r.height*64;if(renderer.focus)renderer.focus(x,y);else {renderer.camera=renderer.iso(x,y);renderer.clampCamera();}};
$('rotate-left').onclick=()=>renderer.rotate?.(40);$('rotate-right').onclick=()=>renderer.rotate?.(-40);$('tilt-camera').onclick=()=>{if(renderer.rotate)renderer.rotate(0,((renderer.elevation>.95?.52:renderer.elevation>.65?1.12:.8)-renderer.elevation)/.004);};$('view-toggle').onclick=()=>{document.body.classList.toggle('cinematic');$('view-toggle').title=document.body.classList.contains('cinematic')?'Mostrar interfaz':'Ocultar interfaz';};
$('modal-overlay').addEventListener('click',e=>{if(e.target===$('modal-overlay'))closeModal();});
let pointer=null,painting=false,pointerActive=false,lineStart=null;
const canvas=$('world');
function coords(e){const r=canvas.getBoundingClientRect();return {x:e.clientX-r.left,y:e.clientY-r.top};}
function cancelLine(){lineStart=null;painting=false;pointer=null;pointerActive=false;if(renderer)renderer.linePreview=null;}
function previewLineAt(p){if(!lineStart||!mode)return;const end=renderer.pick(p.x,p.y);renderer.hover=end;renderer.linePreview=world.previewLine(mode,lineStart,end);updateHint();}
function actAt(p){const t=renderer.pick(p.x,p.y);renderer.hover=t;if(world.gameOver){toast('La partida ha terminado. Puedes empezar un nuevo valle desde el menú.');return;}if(mode){const result=world.place(mode,t.x,t.y);if(!result.ok){if(mode!=='road'&&mode!=='bridge')toast(result.reason,'danger');}else{renderer.invalidate();if(result.building){toast(`Obra iniciada: ${BUILDINGS[mode].name.toLowerCase()}.`);if(world.idle===0)toast('Libera un trabajador para que la obra avance.','danger');if(mode==='quarry'){selectBuilding(result.building.id);toast('Cantera seleccionada: consulta la reserva de piedra en el panel.');}}updateUI();}return;}if(renderer.gatherMode){const r=world.markGather(t.x,t.y);if(r.ok){toast('Recurso marcado. Los trabajadores libres se encargarán.');renderer.invalidate();}else toast(r.reason,'danger');return;}const id=renderer.pickBuilding(p.x,p.y);if(id)selectBuilding(id);else closeSelection();}
canvas.addEventListener('pointerdown',e=>{if(e.button===2&&painting){cancelLine();updateHint();return;}const p=coords(e);pointer={x:p.x,y:p.y,lastX:p.x,lastY:p.y,moved:false,button:e.button};pointerActive=true;canvas.setPointerCapture(e.pointerId);painting=(mode==='road'||mode==='bridge')&&e.button===0;if(painting){lineStart=renderer.pick(p.x,p.y);previewLineAt(p);}hideTooltip();});
canvas.addEventListener('pointermove',e=>{const p=coords(e);renderer.hover=renderer.pick(p.x,p.y);if(pointer&&pointerActive){const distance=Math.hypot(p.x-pointer.x,p.y-pointer.y);if(distance>6)pointer.moved=true;if(painting)previewLineAt(p);else if(pointer.moved){if((pointer.button===2||e.shiftKey)&&renderer.rotate)renderer.rotate(p.x-pointer.lastX,p.y-pointer.lastY);else renderer.pan(p.x-pointer.lastX,p.y-pointer.lastY);canvas.classList.add('dragging');}pointer.lastX=p.x;pointer.lastY=p.y;}updateHint();});
canvas.addEventListener('pointerup',e=>{if(painting&&lineStart){const end=renderer.pick(coords(e).x,coords(e).y),result=world.placeLine(mode,lineStart,end);if(result.ok){renderer.invalidate();if(result.count){toast(`${mode==='road'?'Camino':'Puente'} construido: ${result.count} tramos.`);save(false);}else toast('Ese tramo ya estaba construido.');}else toast(result.reason,'danger');cancelLine();updateUI();}else if(pointer&&!pointer.moved&&pointer.button===0)actAt(coords(e));pointer=null;pointerActive=false;canvas.classList.remove('dragging');updateHint();});
