const keys=new Set();window.addEventListener('keydown',e=>{if(e.target.tagName==='INPUT')return;if(!$('modal-overlay').hidden){if(e.key==='Escape')closeModal();if(e.key==='Tab'){const focusable=[...$('modal').querySelectorAll('button:not(:disabled),input,a')],first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault();}}return;}if([' ','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key))e.preventDefault();if(e.repeat){keys.add(e.key.toLowerCase());return;}if(e.key===' '){togglePause();return;}if(e.key==='Escape'){cancelMode();closeSelection();$('sidebar').classList.remove('open');}else if(e.key==='1')setSpeed(1);else if(e.key==='2')setSpeed(2);else if(e.key==='3')setSpeed(5);else if(e.key.toLowerCase()==='g')toggleGather();else if(e.key.toLowerCase()==='c')renderer.center();else if(e.key.toLowerCase()==='b')chooseBuilding('house');else if(e.key.toLowerCase()==='f')chooseBuilding('farm');else keys.add(e.key.toLowerCase());});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>keys.clear());
new ResizeObserver(()=>renderer.resize()).observe($('game-area'));
window.addEventListener('beforeunload',()=>save(false));document.addEventListener('visibilitychange',()=>{if(document.hidden)save(false);lastTime=0;});
function frame(ms){const now=ms/1000,dt=lastTime?Math.min(1,now-lastTime):0;lastTime=now;if(!$('modal-overlay').hidden)keys.clear();if(!document.hidden){const speed=dt*350;if(keys.has('a')||keys.has('arrowleft'))renderer.pan(speed,0);if(keys.has('d')||keys.has('arrowright'))renderer.pan(-speed,0);if(keys.has('w')||keys.has('arrowup'))renderer.pan(0,speed);if(keys.has('s')||keys.has('arrowdown'))renderer.pan(0,-speed);if(keys.has('q'))renderer.rotate?.(dt*100);if(keys.has('e'))renderer.rotate?.(-dt*100);if(world.speed){accumulator+=dt*world.speed;while(accumulator>=2.5){const latest=world.events[0]?.id;world.tick();accumulator-=2.5;if(world.events[0]?.id!==latest&&['danger','milestone','success'].includes(world.events[0].type))toast(world.events[0].text,world.events[0].type);updateUI();}}world.animate(Math.min(.1,dt),now);renderer.draw(now);if(now-lastUi>1){updateUI();lastUi=now;}if(now-lastSave>20){save(false);lastSave=now;}}
 requestAnimationFrame(frame);}
